insert into public.discover_tools (slug, title, description, topic, kind, minutes, position)
values
  ('where-anxiety-shows-up', 'Where anxiety shows up in your body', 'Choose the physical sensations you notice when you feel anxious. Most people are surprised how many of them they had stopped counting.', 'Anxiety', 'pick', 4, 0),
  ('what-unsettles-you', 'What unsettles you, and how much', 'Sort everyday situations by how often they leave you on edge. The point is the pattern across them, not any single one.', 'Anxiety', 'sort', 5, 1),
  ('anxiety-patterns', 'How anxiety tends to operate in you', 'Rate how often a set of common anxious habits has been true for you lately. You will see which show up most and which barely feature.', 'Anxiety', 'reflect', 5, 2),
  ('avoid-or-approach', 'Avoid or approach', 'Place things you have been avoiding on a grid of how much you avoid them against how much they matter to you.', 'Anxiety', 'matrix', 6, 3),
  ('anatomy-of-a-spike', 'The anatomy of one anxious moment', 'Walk back through a recent spike of anxiety step by step: what led up to it, what you felt, what you did, and what happened next.', 'Anxiety', 'prompts', 8, 4),
  ('box-breathing', 'Box breathing', 'Four seconds in, four held, four out, four held. A steady square of breath many people use to settle a keyed-up body.', 'Anxiety', 'breathe', 3, 5),
  ('steadying-kit', 'Build your steadying kit', 'Assemble a personal list of things that help you feel more grounded: senses, people, places, phrases, and small actions.', 'Anxiety', 'build', 6, 6),
  ('anxiety-week-map', 'When anxiety peaks across your week', 'Mark the times of day and days of the week when anxiety tends to be loudest. A shape usually appears.', 'Anxiety', 'heat', 3, 7),
  ('anxiety-on-seven-dials', 'Anxiety on seven dials', 'Set a dial for each way anxiety can take up room: how loud it is in your body, how much it steers your choices, how long it lingers. The spread across the dials says more than any single one.', 'Anxiety', 'sliders', 4, 8),
  ('little-things-to-feel-safe', 'The little things you do to feel safe', 'Tick the small precautions you have picked up to keep anxiety at bay. They are so ordinary that most people never think of them as anxiety at all.', 'Anxiety', 'check', 3, 9),
  ('dread-vs-the-day', 'Dread in the morning, the day as it was', 'Each morning, rate how much you are dreading the day. Each evening, rate how hard it actually turned out to be. After a week, the gap between the two lines is the point.', 'Anxiety', 'track', 2, 10),
  ('which-kind-of-anxious', 'Which kind of anxious', 'Anxious is a wide word. Narrow it to the flavor you are actually feeling, find where it sits in your body, and hear what it might be asking for.', 'Anxiety', 'wheel', 3, 11),
  ('smoke-alarm-check', 'The smoke alarm check', 'Treat a wave of anxiety like a smoke alarm going off: check for actual smoke, thank the alarm, and give it two minutes to quiet down. A short exercise for the moment it hits.', 'Anxiety', 'guide', 6, 12),
  ('what-anxiety-asks-for', 'What anxiety asks for, and what else you could give it', 'Turn over cards that show a demand anxiety makes on one side and a smaller, kinder alternative on the other. Keep the ones you could imagine trying.', 'Anxiety', 'flip', 5, 13),
  ('what-you-reach-for-first', 'What you reach for first', 'Rank the things you reach for when anxiety rises, from the one you grab first to the one you get to last. The order shows your reflexes, which is different from what you would choose.', 'Anxiety', 'rank', 4, 14),
  ('what-an-anxious-hour-is-made-of', 'What an anxious hour is made of', 'Think of a typical stretch of feeling anxious and divide 100 points across what your mind was actually doing in it. Anxious time is a mix, and the mix is the useful part.', 'Anxiety', 'allocate', 4, 15),
  ('rules-anxiety-wrote', 'The rules anxiety wrote for you', 'Choose the unspoken rules you find yourself living by to keep anxiety quiet, then put them in order of how tightly you keep them. Seeing them written down is often the first time they look like rules.', 'Anxiety', 'pick', 5, 16),
  ('better-than-you-feared', 'A time it went better than you feared', 'Write about one thing you dreaded that turned out fine, or at least survivable. Anxiety keeps careful records of disasters and almost none of the near misses; this evens the books a little.', 'Anxiety', 'prompts', 8, 17),
  ('when-anxiety-is-on-your-side', 'When anxiety is on your side', 'Sort things anxiety makes you do into the ones that genuinely serve you, the ones that get in your way, and the ones that do both. Not every anxious habit needs to go.', 'Anxiety', 'sort', 5, 18),
  ('how-likely-how-bad', 'How likely, and how bad', 'Place the outcomes you fear on a grid of how likely they really are against how bad they would be if they happened. Anxiety tends to put everything in one corner.', 'Anxiety', 'matrix', 6, 19),
  ('worry-sorter', 'The worry sorter', 'Sort your current worries into ones you can act on, ones you cannot control, and ones you are not sure about yet.', 'Worry', 'sort', 5, 20),
  ('where-your-worry-goes', 'Where your worry goes', 'Divide 100 points across areas of life to show where your worrying attention actually lands.', 'Worry', 'allocate', 4, 21),
  ('what-if-to-what-is', 'From "what if" to "what is"', 'Take one "what if" that has been circling and walk it through a handful of grounding questions.', 'Worry', 'prompts', 7, 22),
  ('worry-habits', 'Your worry habits', 'Rate how often a set of common worry patterns has been true for you lately, from seeking reassurance to worrying about worrying.', 'Worry', 'reflect', 5, 23),
  ('worry-window', 'Set up a worry window', 'Design a short, scheduled slot for worrying on purpose, so the rest of the day has somewhere to send it. An experiment, not a rule.', 'Worry', 'build', 5, 24),
  ('worry-vs-problem-solving', 'Worry or problem solving?', 'Turn over cards that show a worrying thought on one side and the questions that separate worry from real problem solving on the other.', 'Worry', 'flip', 5, 25),
  ('when-worry-fills-the-quiet', 'When worry fills the quiet', 'Mark the times of day and days of the week when worry tends to move in. Worry has favorite hours, and they are usually the ones with the least to do.', 'Worry', 'heat', 3, 26),
  ('seven-days-of-worry-weighed', 'Seven days of worry, weighed', 'Each evening, rate how much of the day went to worrying and how useful that worrying turned out to be. By day four the two bars usually stop matching.', 'Worry', 'track', 2, 27),
  ('fears-under-your-worries', 'The fears under your worries', 'Worries change from week to week, but the fears underneath them tend to repeat. Choose the ones you recognize and put them in the order they come up.', 'Worry', 'pick', 5, 28),
  ('how-your-worry-behaves', 'How your worry behaves, on seven dials', 'Set a dial for each way worry can operate: how easily it starts, how long it runs, how believable it sounds, how much it steers you. The pattern across the dials is the point.', 'Worry', 'sliders', 4, 29),
  ('tells-that-give-worry-away', 'The tells that give worry away', 'Tick the small signs, in your body and your behavior, that show you are worrying before you have noticed you are. Catching worry by its tells is easier than catching it by its thoughts.', 'Worry', 'check', 3, 30),
  ('shelve-it-for-now', 'Shelve it for now', 'A short, timed way to set one worry down on purpose without pretending it is gone: write it in a line, name when you will come back to it, and give your attention to something else for three minutes.', 'Worry', 'guide', 6, 31),
  ('count-the-breath', 'Count the breath, not the worry', 'Four in, a two-second pause, six out, eight times. Counting gives a worried mind a small, boring job to do, and a worried body a slower rhythm to follow.', 'Worry', 'breathe', 2, 32),
  ('whose-worry-is-it', 'Whose worry is it', 'Place your current worries on a grid of how much they are yours to carry against how much thought they get. The corner to look at is where things that are not yours get most of your attention.', 'Worry', 'matrix', 6, 33),
  ('what-actually-settles-a-worry', 'What actually settles a worry', 'Rank the things that make a worry quieter, for you specifically, from most reliable to least. Most people discover that what they reach for and what works are two different lists.', 'Worry', 'rank', 4, 34),
  ('past-present-or-far-ahead', 'Past, present, or far ahead', 'Sort your worries by when the thing you are worrying about actually sits in time: already over, happening now, or a long way off. Each of the three deserves a different response.', 'Worry', 'sort', 5, 35),
  ('a-worry-that-came-true', 'A worry that actually came true', 'Most worries do not come true. Write about one that did, and what happened next. People usually find that the feared thing and the surviving of it were two different sizes.', 'Worry', 'prompts', 9, 36),
  ('what-you-believe-about-worrying', 'What you believe about worrying', 'Rate how much you agree with a set of beliefs people hold about worry itself: that it shows you care, that it keeps bad things away, that it cannot be stopped. Beliefs like these are what keep worry in a job.', 'Worry', 'reflect', 5, 37),
  ('what-worry-has-borrowed', 'What worry has quietly borrowed', 'Choose the things worry has taken from you in the last month, from sleep to a plan you canceled to a good moment you could not quite enjoy. Naming the cost is not self-pity; it is accounting.', 'Worry', 'pick', 4, 38),
  ('three-am-worry-plan', 'A plan for the 3 a.m. worry', 'Decide, in daylight, what you will do when worry wakes you in the middle of the night. A plan made at 3 p.m. is far more use than any decision you make at 3 a.m.', 'Worry', 'build', 6, 39),
  ('slow-the-stream', 'Slow the stream', 'A three-minute noting exercise: watch thoughts arrive and label each one with a single word, without following it anywhere.', 'Racing thoughts', 'guide', 5, 40),
  ('busy-mind-log', 'Seven days of a busy mind', 'Each day, rate how crowded your head felt and how well you could focus. After a few days, the two lines start telling a story.', 'Racing thoughts', 'track', 2, 41),
  ('racing-thoughts-patterns', 'How your thoughts race', 'Rate how often a set of fast-thinking experiences has been true for you lately: jumping topics, losing the thread, thoughts that will not stop at night.', 'Racing thoughts', 'reflect', 5, 42),
  ('thought-parking-lot', 'The thought parking lot', 'Empty everything circling in your head onto the page, then find the one thought that is actually loudest and give it a single next step.', 'Racing thoughts', 'prompts', 6, 43),
  ('mind-weather', 'Today''s mind weather', 'Describe the state of your mind as weather. Picking the closest words is a quick way to notice something that is hard to describe directly.', 'Racing thoughts', 'pick', 3, 44),
  ('what-speeds-your-mind', 'What speeds your mind up and what slows it', 'Sort everyday inputs by what they do to the pace of your thinking. The slowing column is the one most people have never written down.', 'Racing thoughts', 'sort', 5, 45),
  ('fast-mind-week-map', 'When your mind runs fastest', 'Mark the times of day and days of the week when your thoughts tend to speed up. The shape usually points at what is feeding them.', 'Racing thoughts', 'heat', 3, 46),
  ('fast-mind-fuel', 'What feeds a fast mind', 'Tick the everyday habits you recognize. None of them is wrong on its own; together they add up to how much fuel a busy mind is getting.', 'Racing thoughts', 'check', 3, 47),
  ('double-inhale-long-exhale', 'Two breaths in, one long breath out', 'Breathe in, top it up with a second small breath, then let it all out slowly. A quick pattern many people reach for when the mind is sprinting and there is no time to sit down.', 'Racing thoughts', 'breathe', 2, 48),
  ('racing-thoughts-dials', 'Your racing thoughts, dial by dial', 'Set a dial for each quality of the thinking in your head right now: speed, volume, number of threads, stickiness. Two fast minds can be very different from each other.', 'Racing thoughts', 'sliders', 4, 49),
  ('loud-versus-doable', 'Loud versus doable', 'Place the thoughts running right now on a grid of how loud each one is against how much you can actually do about it. Loud and doable are not the same thing.', 'Racing thoughts', 'matrix', 6, 50),
  ('what-a-fast-mind-says', 'What a fast mind tells you', 'Turn over cards that show something a racing mind insists on, and on the back a steadier reply. Keep the ones that sound like something you could actually say to yourself.', 'Racing thoughts', 'flip', 5, 51),
  ('circuit-breaker', 'Build your circuit breaker', 'Assemble a ten-minute plan for the moment you notice your mind sprinting: a first move, somewhere to put the thoughts, something for the body, and one line to say to yourself.', 'Racing thoughts', 'build', 5, 52),
  ('kinds-of-fast-thinking', 'What kind of thinking fills your fast mind', 'Divide 100 points across the kinds of thinking your racing mind does, from planning to replaying to daydreaming. The mix is the story, not the total.', 'Racing thoughts', 'allocate', 4, 53),
  ('what-slows-you-ranked', 'What slows your mind, ranked honestly', 'Put ways of slowing a racing mind in order of how well they actually work for you, not how well they are supposed to. Your top three are your real toolkit.', 'Racing thoughts', 'rank', 4, 54),
  ('half-speed', 'Half speed', 'Move, speak, and breathe at half your usual pace for four short rounds. A fast mind tends to follow a slow body, and this is the quickest way to find out whether yours does.', 'Racing thoughts', 'guide', 5, 55),
  ('tells-of-a-fast-mind', 'How you can tell your mind has sped up', 'Choose the outward signs that appear when your thoughts are racing: the ones you or the people around you could actually see. They are the early warning most of us ignore.', 'Racing thoughts', 'pick', 3, 56),
  ('what-a-fast-mind-costs', 'What a fast mind costs you', 'Rate how often the pace of your thinking has been getting in the way lately: forgotten things, half-heard conversations, decisions made too fast, tired but wired at night.', 'Racing thoughts', 'reflect', 5, 57),
  ('close-park-drop', 'Close it, park it, or drop it', 'Sort the open loops in your head into three piles: ones you can close in two minutes, ones that need a slot in the calendar, and ones you can let go of. Open loops are what a racing mind keeps circling.', 'Racing thoughts', 'sort', 5, 58),
  ('under-the-racing', 'What is under the racing', 'Narrow the feeling that is driving your fast mind from a rough word to a precise one, find where it sits in your body, and hear what it might be asking for.', 'Racing thoughts', 'wheel', 3, 59),
  ('mood-energy-week', 'A week of mood and energy', 'Log your mood, your energy, and your sleep each day for a week. They usually move together, and where they do not is interesting.', 'Low mood', 'track', 2, 60),
  ('fills-and-drains', 'What fills you and what drains you', 'Sort ordinary activities into ones that leave you with more than you started with and ones that leave you with less.', 'Low mood', 'sort', 5, 61),
  ('small-pleasures', 'Small pleasures still within reach', 'Choose ten small pleasures that are genuinely available to you this week. Low mood shrinks the list we can remember; this expands it back.', 'Low mood', 'pick', 4, 62),
  ('low-mood-patterns', 'How low mood shows up for you', 'Rate how often a set of low-mood experiences has been true lately: heaviness, withdrawal, flatness, harsh self-talk.', 'Low mood', 'reflect', 5, 63),
  ('energy-vs-payoff', 'Energy cost versus payoff', 'Place the tasks and activities in front of you on a grid of how much energy they take against how much they give back.', 'Low mood', 'matrix', 6, 64),
  ('tiny-first-step', 'The tiny first step', 'Build a plan for a hard day that is small enough to actually happen: one thing for the body, one for the room, one for connection.', 'Low mood', 'build', 5, 65),
  ('hard-day-self-talk', 'Self-talk for hard days', 'Turn over cards that show a common harsh thought on one side and a fairer way of saying the same thing on the other. Keep the ones that ring true.', 'Low mood', 'flip', 5, 66),
  ('what-changed', 'What changed, and when', 'Trace back to when your mood started to shift and look at what was different before and after. Sometimes there is a reason hiding in plain sight.', 'Low mood', 'prompts', 7, 67),
  ('low-mood-week-map', 'When the low patch is heaviest', 'Mark the times of day and days of the week when your mood tends to sit lowest. Most people find a shape they had felt but never seen.', 'Low mood', 'heat', 3, 68),
  ('low-patch-dials', 'The shape of this low patch', 'Set a dial for each part of how low mood is sitting with you right now: heaviness, interest, appetite for people, pace, hope. Two low patches can have very different shapes.', 'Low mood', 'sliders', 4, 69),
  ('how-much-smaller', 'How much smaller life has gotten', 'Tick the ways your world has quietly shrunk lately. Low mood tends to narrow life in small, reasonable-looking steps, so most of these go unnoticed until they are listed.', 'Low mood', 'check', 3, 70),
  ('waking-breath', 'The waking breath', 'Three seconds in through the nose, three seconds out through the mouth, sitting up. A brisker, even rhythm for the mornings when the body does not want to start.', 'Low mood', 'breathe', 2, 71),
  ('five-minutes-before-and-after', 'Five minutes, before and after', 'Rate your mood, do one small thing for five minutes, rate it again. A tiny experiment in whether action can move mood, run with your own numbers rather than anyone else''s claims.', 'Low mood', 'guide', 8, 72),
  ('what-to-protect', 'What to protect when the tank is low', 'Put the basics in order of what you would protect first when energy is scarce. On a low day, not everything can be kept up, and deciding in advance is easier than deciding while in it.', 'Low mood', 'rank', 4, 73),
  ('where-a-low-day-goes', 'Where a low day''s hours go', 'Divide 100 points across how the waking hours of a typical low day actually go: in bed awake, scrolling, obligations, screens, outside, with people. Seeing it in bars is different from knowing it vaguely.', 'Low mood', 'allocate', 4, 74),
  ('under-the-low', 'What is under the low', 'Narrow the feeling inside a low patch from a rough word to a precise one, find where it sits in your body, and hear what it might be asking for. "Low" covers a lot of different things.', 'Low mood', 'wheel', 3, 75),
  ('fact-or-mood-talking', 'A fact, or the mood talking?', 'Sort the kinds of things a low day says into facts, mood-talk, and not sure. They arrive in the same voice, which is why the mood''s version is so convincing.', 'Low mood', 'sort', 5, 76),
  ('note-to-the-next-low-day', 'A note for the next low day', 'Write a short note today, from a slightly better place, to be read on the next hard day: what helped, what not to believe, who to call. Future you will not remember any of it without this.', 'Low mood', 'prompts', 8, 77),
  ('daylight-people-mood-week', 'Mood, daylight, and people: a week', 'Log your mood, how much daylight you got, and how much real contact you had, each day for a week. Two of these are things you can change; the third tends to follow them.', 'Low mood', 'track', 2, 78),
  ('who-helps-on-a-low-day', 'Who helps on a low day', 'Place the people in your life on a grid of how much effort it takes to see them against how you feel afterward. On a low day, effort and afterglow do not always line up.', 'Low mood', 'matrix', 6, 79),
  ('stress-load-dials', 'Your stress load, area by area', 'Set a dial for how much stress each area of life is carrying right now. Seeing them side by side shows where the weight really is.', 'Stress & burnout', 'sliders', 4, 80),
  ('burnout-signals', 'Early signals of running on empty', 'Tick the signs of depletion you recognize from the last couple of weeks. Most people miss the early ones until they are pointed out.', 'Stress & burnout', 'check', 3, 81),
  ('energy-budget', 'Your weekly energy budget', 'Divide 100 points across where your energy actually went this week. Then compare it with where you wish it had gone.', 'Stress & burnout', 'allocate', 4, 82),
  ('recovery-menu', 'Build your recovery menu', 'Assemble a menu of rest options in three sizes: five minutes, an hour, and a whole day. Rest is easier to take when it is already chosen.', 'Stress & burnout', 'build', 5, 83),
  ('stress-signature', 'Your stress signature', 'Rate how often a set of stress responses has been true lately, across body, mood, thinking, and behavior. Everyone has a signature; this helps you read yours.', 'Stress & burnout', 'reflect', 5, 84),
  ('demands-and-resources', 'Demands and resources', 'Sort what is on your plate into things that take from you and things that give to you. Stress tends to follow the balance between them.', 'Stress & burnout', 'sort', 5, 85),
  ('four-seven-eight-breath', 'The 4-7-8 breath', 'Breathe in for four, hold for seven, out for eight. A long exhale that many people find useful when the body will not wind down.', 'Stress & burnout', 'breathe', 3, 86),
  ('when-you-let-up', 'When you actually let up', 'Mark the times in your week when you genuinely stop: not waiting, not scrolling, not half-working. Most people find the map is emptier than they expected.', 'Stress & burnout', 'heat', 3, 87),
  ('pressure-and-release-log', 'Seven days of pressure and release', 'Each day, rate how much pressure you were under, how much of it you set down by evening, and how much say you had in your day. The gap between the first two lines is the one to watch.', 'Stress & burnout', 'track', 2, 88),
  ('what-you-drop-first', 'What you drop first', 'Put the things that hold you up in the order you let them go when life gets busy. The top of the list is where a hard stretch starts costing you.', 'Stress & burnout', 'rank', 4, 89),
  ('the-voice-that-says-keep-going', 'The voice that says keep going', 'Turn over the lines that keep you pushing past empty, and read a steadier reply on the back. Keep the ones that would actually stop you mid-sentence.', 'Stress & burnout', 'flip', 5, 90),
  ('heavy-and-yours', 'Heavy or light, yours or not', 'Place what you are carrying on a grid of how heavy it feels against how much of it is really yours to hold. The heaviest box is not always the one that needs you.', 'Stress & burnout', 'matrix', 6, 91),
  ('where-you-learned-to-push-through', 'Where you learned to push through', 'Trace the rule that says you keep going no matter what back to where you picked it up. Rules are easier to bend once you know whose they were.', 'Stress & burnout', 'prompts', 8, 92),
  ('the-quiet-stressors', 'The quiet stressors', 'Choose the low-level things that hum away under the big ones: the ones you would never list as stress but which never fully switch off. They are often the easiest to change.', 'Stress & burnout', 'pick', 4, 93),
  ('reset-between-tasks', 'A reset between tasks', 'A two-minute pause for the gap between one thing and the next, so the tension of the last task does not walk straight into the new one.', 'Stress & burnout', 'guide', 3, 94),
  ('the-double-inhale', 'The double inhale', 'Two breaths in through the nose, one on top of the other, then a long slow breath out. A quick way many people use to take the edge off in the middle of a busy day.', 'Stress & burnout', 'breathe', 2, 95),
  ('why-you-said-yes', 'Why you said yes', 'List the things you agreed to this month and sort them by the real reason: because you wanted to, because you felt you should, or because nobody else would. Stress often hides in the second and third columns.', 'Stress & burnout', 'sort', 5, 96),
  ('rest-that-rests', 'Rest that rests, and rest that does not', 'Rate how often your time off actually leaves you restored. Plenty of people get hours of rest and none of the benefit, and the reasons are usually visible.', 'Stress & burnout', 'reflect', 5, 97),
  ('where-the-pressure-comes-from', 'Where the pressure is coming from', 'Divide 100 points across the sources of pressure in your life right now, including the one that is you. Most people are surprised by how many points end up in that last bar.', 'Stress & burnout', 'allocate', 4, 98),
  ('the-last-time-you-felt-rested', 'The last time you felt rested', 'Write your way back to a time you felt genuinely restored, and look at what was true then. The conditions of rest are more specific than people assume.', 'Stress & burnout', 'prompts', 7, 99),
  ('sleep-week-log', 'A week of sleep, honestly', 'Rate how easily you fell asleep, how you slept, and how you felt the next morning. A week of honest entries shows more than any single bad night.', 'Sleep', 'track', 2, 100),
  ('wind-down-routine', 'Design your wind-down', 'Build a realistic last hour before bed from things you would actually do, not an ideal routine you would abandon by Wednesday.', 'Sleep', 'build', 5, 101),
  ('what-keeps-you-up', 'What keeps you up', 'Sort the things that visit at bedtime into what they are made of: unfinished tasks, worries, replays, or body restlessness. Each one wants a different response.', 'Sleep', 'sort', 4, 102),
  ('sleep-habits-check', 'Sleep habits worth a look', 'Tick the everyday habits that are true for you. None of them is a verdict; together they show where sleep might be getting crowded.', 'Sleep', 'check', 3, 103),
  ('body-scan-for-rest', 'A body scan for rest', 'Move your attention slowly from your feet to your head, noticing and softening as you go. Often used in bed; usable anywhere.', 'Sleep', 'guide', 8, 104),
  ('when-tiredness-lands', 'When tiredness lands', 'Mark when across the week you feel sleepiest, from the mid-afternoon slump to the second wind at midnight. The shape says a lot about where your sleep is being spent.', 'Sleep', 'heat', 3, 105),
  ('what-to-say-at-three-am', 'What to say to yourself at 3 a.m.', 'Turn over the thoughts that arrive when you wake in the night, and find a steadier reply on the back. Keep the ones that would actually quiet you.', 'Sleep', 'flip', 5, 106),
  ('evening-pleasures-and-sleep', 'Evening pleasures against sleep', 'Place what you do in the evenings on a grid of how much you enjoy it against how much it helps you sleep. Not everything that costs sleep has to go, but it helps to know which ones you are paying for.', 'Sleep', 'matrix', 5, 107),
  ('how-you-wake-up', 'How you wake up', 'Set a dial for each part of your mornings: getting up, the first hour, mood, appetite, and when the day starts to feel manageable. The waking side of sleep gets far less attention than the falling-asleep side.', 'Sleep', 'sliders', 4, 108),
  ('how-much-sleep-is-on-your-mind', 'How much sleep is on your mind', 'Rate how often sleep occupies your thinking during the day and your effort at night. For some people the trying has become heavier than the tiredness.', 'Sleep', 'reflect', 5, 109),
  ('where-the-evening-goes', 'Where the evening goes', 'Divide 100 points across how the hours between dinner and bed were actually spent this week. The evening is where sleep is made or spent, and most of us have never looked at it.', 'Sleep', 'allocate', 4, 110),
  ('what-short-sleep-takes-first', 'What short sleep takes first', 'Put in order what goes first when you are short on sleep: patience, focus, humor, appetite, warmth. Knowing your order makes a rough night easier to plan around.', 'Sleep', 'rank', 4, 111),
  ('daylight-movement-sleep', 'Daylight, movement, sleep', 'Each day, rate how much daylight you got, how much you moved, and how you slept that night. Sleep is often decided before noon, and a week of entries tends to show it.', 'Sleep', 'track', 2, 112),
  ('your-sleep-story', 'Your sleep story', 'Write about how you have slept across your life: as a child, in the easiest stretch, and now. Seeing sleep as a story with chapters loosens the belief that this chapter is the only one.', 'Sleep', 'prompts', 8, 113),
  ('your-three-am-plan', 'Your 3 a.m. plan', 'Decide in daylight what you will do when you are awake in the night, so there is a plan to follow instead of a fight with the pillow. Plans made at 3 a.m. are rarely good ones.', 'Sleep', 'build', 5, 114),
  ('four-in-six-out', 'Four in, six out', 'A gentle bedtime rhythm: breathe in for four, out for six, with no holds to count. It is simple enough to keep going as the mind loosens.', 'Sleep', 'breathe', 3, 115),
  ('sleepy-signals', 'The sleepy signals you push past', 'Choose the signs that tell you your body is ready for sleep, including the ones you regularly ignore for one more episode. Answering the first signal is easier than chasing sleep an hour later.', 'Sleep', 'pick', 3, 116),
  ('what-you-do-instead-of-sleeping', 'What you do instead of sleeping', 'Choose and rank what fills the hour you meant to spend asleep. Often it is the only hour of the day that is yours, which is why it is so hard to give up.', 'Sleep', 'pick', 4, 117),
  ('your-bedroom-dial-by-dial', 'Your bedroom, dial by dial', 'Set a dial for each thing the room itself contributes: dark, quiet, cool, comfortable, tidy, screen-free, and whether it feels like a place for rest. The room is the one part of sleep you can change with your hands.', 'Sleep', 'sliders', 3, 118),
  ('sleep-advice-sorted', 'Sleep advice, sorted', 'Sort the advice you have been given about sleep into what you tried and found helpful, what you tried and did not, and what you have never actually tested. The third column is usually longer than expected.', 'Sleep', 'sort', 5, 119),
  ('what-you-value-in-closeness', 'What you value most in closeness', 'Choose and rank the five things that matter most to you in a close relationship. Knowing your own list makes it easier to see when it is being met.', 'Relationships', 'pick', 5, 120),
  ('one-relationship-dials', 'One relationship, five dials', 'Think of one important relationship and set a dial for trust, ease, honesty, reciprocity, and closeness. It works for a partner, a friend, or a family member.', 'Relationships', 'sliders', 4, 121),
  ('how-you-show-up-in-conflict', 'How you show up in conflict', 'Rate how often a set of conflict habits has been true for you: going quiet, getting loud, fixing, fleeing, keeping score.', 'Relationships', 'reflect', 5, 122),
  ('conflict-moves-sorter', 'Your conflict moves', 'Sort a list of things people do during disagreements into what you do often, sometimes, and rarely. Then look at what your "often" list has in common.', 'Relationships', 'sort', 5, 123),
  ('from-frustration-to-ask', 'From frustration to a clear ask', 'Take one frustration with someone close to you and work it into a need and a request they could actually say yes to.', 'Relationships', 'prompts', 7, 124),
  ('appreciation-inventory', 'An appreciation inventory', 'Write down what you appreciate about one person in your life, specifically enough that it could only be about them. Then decide whether to tell them.', 'Relationships', 'prompts', 6, 125),
  ('support-circle-map', 'Your support circle', 'Place the people in your life on a grid of how close they feel against how much you actually lean on them. The gaps are often revealing.', 'Relationships', 'matrix', 6, 126),
  ('repair-after-conflict', 'Repair after conflict', 'Turn over cards showing what people often want to say after a fight on one side and what tends to reach the other person on the other.', 'Relationships', 'flip', 5, 127),
  ('friendship-drift-signs', 'When a friendship is drifting', 'Think of one friend you have felt further from lately and tick the small signs of drift you recognize. Drift is quiet, and naming it early is most of the work of stopping it.', 'Relationships', 'check', 4, 128),
  ('where-your-effort-goes', 'Where your relationship effort goes', 'Divide 100 points across the people in your life to show where your effort actually lands: the messages, the visits, the remembering, the showing up.', 'Relationships', 'allocate', 4, 129),
  ('when-you-actually-talk', 'When you actually talk', 'Mark the times in your week when you and the person you live with have a real conversation, not logistics or a screen between you. Most couples and roommates find the map is emptier than they assumed.', 'Relationships', 'heat', 3, 130),
  ('how-to-help-me', 'How to help me when I am struggling', 'Rank the ways people try to help from most to least useful for you. Then you have a list you could actually hand to a partner, friend, or family member.', 'Relationships', 'rank', 4, 131),
  ('seven-days-of-contact', 'Seven days of contact', 'Each evening, rate how connected you felt to other people, how much you reached out, and how much others reached you. By the weekend, the three lines start to explain each other.', 'Relationships', 'track', 2, 132),
  ('friendship-upkeep-routine', 'Keeping friendships alive', 'Build a small, realistic routine for the friendships that matter to you: the low-effort touches, the rituals, and what you do when one of you is struggling.', 'Relationships', 'build', 6, 133),
  ('before-you-hit-send', 'Before you hit send', 'A short exercise for the message you are about to send in a heated moment, whether to a partner, a group chat, or a coworker. Five minutes between the draft and the send button.', 'Relationships', 'guide', 6, 134),
  ('when-they-go-quiet', 'When they go quiet', 'Turn over the stories your mind writes when someone does not reply, cancels, or goes distant, and see the other explanations and the question you could ask instead.', 'Relationships', 'flip', 5, 135),
  ('invisible-load-at-home', 'The invisible load at home', 'Place the jobs that keep a home running on a grid of who mostly does them against how visible they are. For couples and roommates, the bottom corners are where the arguments come from.', 'Relationships', 'matrix', 6, 136),
  ('roles-you-play', 'The roles you play with people', 'Choose the parts you tend to play in your relationships: the planner, the listener, the fixer, the one who fades. Then look at which ones you chose and which ones were handed to you.', 'Relationships', 'pick', 5, 137),
  ('conversation-you-keep-putting-off', 'The conversation you keep putting off', 'Write your way toward a conversation with a family member or someone close that you have been avoiding. Not to rehearse a speech, but to find out what you actually want from it.', 'Relationships', 'prompts', 8, 138),
  ('what-you-say-at-work', 'What you say to coworkers, and what you swallow', 'Sort things people could say to a coworker into what you say readily, what you say eventually, and what you never say. The last column is where work relationships get stuck.', 'Relationships', 'sort', 5, 139),
  ('saying-no-dials', 'How easily you say no', 'Set a dial for how comfortable you are saying no in different parts of your life. Most people find it varies more than they expected.', 'Boundaries', 'sliders', 4, 140),
  ('yes-no-maybe', 'Yes, no, or maybe', 'Sort the requests and obligations currently on you into a real yes, a real no, and a maybe. Then look at how many of your yeses were actually maybes.', 'Boundaries', 'sort', 5, 141),
  ('boundary-phrases', 'Boundary phrases you would actually say', 'Build a short set of phrases for declining, delaying, and holding a line, in words that sound like you rather than like a script.', 'Boundaries', 'build', 5, 142),
  ('where-you-overextend', 'Where you overextend', 'Rate how often a set of overextending habits has been true lately: saying yes on reflex, apologizing for needs, doing the emotional work for everyone.', 'Boundaries', 'reflect', 5, 143),
  ('yes-that-meant-no', 'The signs you said yes when you meant no', 'Tick the after-the-fact signals you recognize from times you agreed to something you did not want. These show up before the resentment does, and they are easier to catch.', 'Boundaries', 'check', 3, 144),
  ('when-they-push-back', 'When they push back', 'Turn over the lines people use when you hold a boundary, from guilt trips to "just this once", and see what is happening underneath and what you could say without folding.', 'Boundaries', 'flip', 5, 145),
  ('who-asks-who-you-cant-refuse', 'Who asks, and who you can''t refuse', 'Place the people who make requests of you on a grid of how often they ask against how hard it is to say no to them. Two of the corners are where your time actually disappears.', 'Boundaries', 'matrix', 6, 146),
  ('the-line-that-keeps-moving', 'The line that keeps moving', 'Trace one boundary you have set before and watched slide: how it was drawn, how it eroded, and what it would take to hold it. Most lines do not get crossed all at once.', 'Boundaries', 'prompts', 7, 147),
  ('what-a-no-might-cost', 'What you are afraid a no will cost', 'Choose the fears that come up when you consider saying no, then rank them. Seeing the actual fear makes it possible to check whether it is true.', 'Boundaries', 'pick', 5, 148),
  ('which-lines-you-hold', 'Which lines are easiest to hold', 'Rank kinds of boundaries from easiest to hardest for you to keep: your time, your body, your money, your phone, your opinions, your privacy. Your order says a lot about where you were taught you had a say.', 'Boundaries', 'rank', 4, 149),
  ('what-your-yeses-are-made-of', 'What your yeses are made of', 'Divide 100 points across the reasons you say yes, from genuinely wanting to, to avoiding a fight, to reflex. The bars show how much of your agreement is actually agreement.', 'Boundaries', 'allocate', 4, 150),
  ('when-your-time-stops-being-yours', 'When your time stops being yours', 'Mark the times of the week when other people''s needs take over your time: the after-hours messages, the drop-ins, the calls you always answer. A pattern usually appears.', 'Boundaries', 'heat', 3, 151),
  ('seven-days-of-yes-and-no', 'Seven days of yes and no', 'Each evening, rate how much of the day felt like yours, how many things you agreed to that you did not want, and how you felt after any no you managed to say. A week of this shows where the leaks are.', 'Boundaries', 'track', 2, 152),
  ('the-pause-before-you-answer', 'The pause before you answer', 'A four-minute exercise for the moment someone asks you for something. Practice it with a recent request so the pause is there when the next one arrives.', 'Boundaries', 'guide', 5, 153),
  ('whose-job-is-it', 'Whose job is it', 'Sort a list of things people carry into mine, theirs, and shared. Many of the heaviest things we carry were never ours to pick up.', 'Boundaries', 'sort', 5, 154),
  ('family-visit-plan', 'Your plan for the next family visit', 'Build a small plan for a visit home or a family gathering: how long you will stay, what you will not discuss, what you will do when it gets hard, and how you will land afterwards.', 'Boundaries', 'build', 6, 155),
  ('how-you-take-a-no', 'How you take other people''s no', 'Boundaries run both ways. Rate how often you keep pushing after someone has said no, read into "I''m busy", or show up when you were not invited. Most people have never looked at this side of it.', 'Boundaries', 'reflect', 5, 156),
  ('how-reachable-you-are', 'How reachable you let yourself be', 'Set a dial for how available you are through your phone and screens: work messages after hours, group chats, reply speed, notifications at night. Availability is a boundary most people never set on purpose.', 'Boundaries', 'sliders', 4, 157),
  ('work-boundaries-check', 'Work boundaries worth a look', 'Tick the things you do at work or school that quietly hand your time, credit, or energy to other people. None of them is a big deal on its own. Together they add up to a job you did not sign up for.', 'Boundaries', 'check', 3, 158),
  ('write-it-then-cut-it', 'Write the message, then cut it in half', 'Draft a boundary message to someone, then take it through four edits: strip the apology, strip the excuse, keep the warmth, check the ask. What is left is usually shorter, kinder, and clearer.', 'Boundaries', 'prompts', 7, 159),
  ('inner-critic-inner-ally', 'Inner critic, inner ally', 'Turn over cards that show what an inner critic says on one side and what an inner ally would say about the same thing on the other.', 'Self-esteem', 'flip', 5, 160),
  ('your-strengths', 'Your strengths, chosen and ranked', 'Pick the five strengths that are most truly yours from a long list, then rank them. Not the ones you wish you had; the ones people would recognize.', 'Self-esteem', 'pick', 5, 161),
  ('how-you-talk-to-yourself', 'How you talk to yourself', 'Rate how often a set of self-talk habits has been true lately, from harsh comparisons to generous self-forgiveness.', 'Self-esteem', 'reflect', 5, 162),
  ('self-compassion-letter', 'A letter from the kind version of you', 'Write to yourself about something you are struggling with, from the perspective of someone who loves you and knows everything about you.', 'Self-esteem', 'prompts', 10, 163),
  ('comparison-habits', 'Your comparison habits', 'Tick the ways you find yourself measuring against other people. Everyone compares; the question is when, with whom, and what it does to you.', 'Self-esteem', 'check', 3, 164),
  ('what-you-would-tell-a-friend', 'What you would tell a friend', 'Describe your situation as if it were happening to a friend, then answer them. A quick way to hear how much harsher you are on yourself.', 'Self-esteem', 'prompts', 6, 165),
  ('how-you-relate-to-your-body', 'How you relate to your body', 'Set a handful of dials about your relationship with your body: trust, care, criticism, gratitude, ease. Not about how it looks; about how you live in it.', 'Self-esteem', 'sliders', 4, 166),
  ('what-your-worth-rides-on', 'What your worth is riding on', 'Sort the conditions people attach to feeling okay about themselves by how much yours depends on each one. Worth that rides on a condition wobbles every time the condition does.', 'Self-esteem', 'sort', 5, 167),
  ('whose-opinion-counts', 'Whose opinion counts', 'Divide 100 points across the people whose opinions shape how you feel about yourself. Most people are surprised by how few points they give to their own.', 'Self-esteem', 'allocate', 4, 168),
  ('skill-against-credit', 'Skill against credit', 'Place things you do on a grid of how good you actually are at them against how much credit you give yourself. The gap between the two is where a lot of low self-esteem lives.', 'Self-esteem', 'matrix', 6, 169),
  ('evidence-file', 'Build your evidence file', 'The inner critic works from a very selective file. Assemble a plan for keeping the rest of the record: what counts as evidence, where it lives, when you add to it, and when you read it.', 'Self-esteem', 'build', 6, 170),
  ('self-regard-week', 'A week of how you rated yourself', 'Each evening, rate how you felt about yourself alongside how much you got done and how much approval you received. After a few days you can see what your self-regard is actually pegged to.', 'Self-esteem', 'track', 2, 171),
  ('how-you-earn-approval', 'How you earn approval', 'Rank the moves you use to be liked, from the one you reach for most to the one you rarely use. Everyone has a few; the top two usually started young and worked.', 'Self-esteem', 'rank', 4, 172),
  ('critic-week-map', 'When your inner critic is loudest', 'Mark the times in your week when the critical voice gets going. Self-criticism keeps a schedule, and the schedule usually points to what feeds it.', 'Self-esteem', 'heat', 3, 173),
  ('taking-a-compliment', 'Taking a compliment in', 'A short, timed exercise in letting something kind land instead of batting it away. Deflecting compliments is a habit, and this is one repetition in the other direction.', 'Self-esteem', 'guide', 4, 174),
  ('space-you-take-up', 'How much space you take up', 'Rate how often you make yourself smaller than you are: in doorways, in conversations, in what you ask for. Shrinking usually starts as politeness and turns into a reflex.', 'Self-esteem', 'reflect', 5, 175),
  ('messages-you-grew-up-with', 'Messages you grew up with', 'Tick the things you were told about yourself growing up, in words or otherwise. Messages heard young tend to get mistaken for facts.', 'Self-esteem', 'check', 3, 176),
  ('where-the-bar-came-from', 'Where the bar came from', 'Write your way to the standard you hold yourself to, who set it, and what happens when you reach it. A bar that moves every time you get there is not a standard.', 'Self-esteem', 'prompts', 8, 177),
  ('what-you-apologize-for', 'What you keep apologizing for', 'Choose the things you find yourself saying sorry for, out loud or in your head. Most of them are not offenses; each apology is a small admission that you were not supposed to need or be that.', 'Self-esteem', 'pick', 4, 178),
  ('where-your-confidence-lives', 'Where your confidence lives', 'Set a dial for how sure of yourself you feel in each area of life. Confidence is rarely one thing; most people have a couple of high dials and judge themselves by the low ones.', 'Self-esteem', 'sliders', 4, 179),
  ('feelings-wheel', 'The feelings wheel', 'Narrow a vague feeling down to a precise word, find where it sits in your body, and hear what it might be asking for.', 'Emotions', 'wheel', 3, 180),
  ('this-weeks-feelings', 'The feelings you had this week', 'Choose the feeling words that visited you this week from a wide list. Most people use a handful of words for hundreds of feelings; this stretches the vocabulary.', 'Emotions', 'pick', 4, 181),
  ('big-feelings-week-map', 'When big feelings arrive', 'Mark the times in your week when strong emotions tend to surface. Feelings often keep a schedule we have not noticed.', 'Emotions', 'heat', 3, 182),
  ('feel-name-need', 'Feel it, name it, find the need', 'Take one feeling you are having right now through three steps: what it is, where it came from, and what it wants.', 'Emotions', 'prompts', 6, 183),
  ('feelings-you-avoid', 'Feelings you let in and feelings you avoid', 'Sort emotions into ones you can sit with, ones you tolerate, and ones you tend to leave the room to escape. Avoided feelings tend to run the show from offstage.', 'Emotions', 'sort', 4, 184),
  ('emotional-weather-log', 'Seven days of emotional weather', 'Rate the intensity and pleasantness of your feelings each day, and how well you could name what you felt. A week shows range as well as mood.', 'Emotions', 'track', 2, 185),
  ('ride-the-wave', 'Ride the wave', 'A short, timed exercise for staying with a feeling as it rises and falls instead of fighting or feeding it.', 'Emotions', 'guide', 5, 186),
  ('how-you-let-feelings-out', 'How you let feelings out', 'Rate how often each of these describes what you do with a feeling once you have it. Feelings that are held in do not disappear; they tend to find their own exit.', 'Emotions', 'reflect', 5, 187),
  ('shape-of-your-feelings', 'The shape of your feelings', 'Set dials for how your feelings behave: how fast they arrive, how strong they get, how long they stay, how visible they are. There is no right shape, but knowing yours helps.', 'Emotions', 'sliders', 4, 188),
  ('feelings-showing-up-sideways', 'Feelings that show up sideways', 'Tick the signs that a feeling is being carried but not felt. When an emotion gets no room, it usually finds another route out: the body, the temper, or the tear ducts at odd moments.', 'Emotions', 'check', 3, 189),
  ('feeling-rules', 'Feeling rules, turned over', 'Turn over cards that show a rule about feelings on one side and another way of seeing it on the other. Most of these rules were true somewhere once, and are still quietly enforcing themselves.', 'Emotions', 'flip', 5, 190),
  ('double-breath-sigh', 'The double-breath sigh', 'Two breaths in through the nose, the second one a small top-up, then one long, slow breath out through the mouth. It is the sigh your body does on its own after crying; done on purpose it takes the edge off a feeling that has built up.', 'Emotions', 'breathe', 2, 191),
  ('where-each-feeling-goes', 'Where each feeling goes', 'Build a plan for where each of your feelings can actually go: which person, place, or practice gets your sadness, your anger, your fear, your joy. A feeling with nowhere to go tends to go inward.', 'Emotions', 'build', 6, 192),
  ('felt-versus-shown', 'Felt versus shown', 'Place the people and settings in your life on a grid of how much you feel around them against how much of it you show. The gap between the two says a lot about where you are yourself.', 'Emotions', 'matrix', 6, 193),
  ('hardest-to-say-out-loud', 'Hardest to say out loud', 'Rank ten feeling sentences from the one you could say tomorrow to the one you can barely imagine saying. The bottom of the list is usually where the most would change.', 'Emotions', 'rank', 4, 194),
  ('emotional-energy-budget', 'Where your emotional energy went', 'Divide 100 points across where your feelings were spent this week: the people, situations, and thoughts that took the most out of you, whether or not they gave anything back.', 'Emotions', 'allocate', 4, 195),
  ('feelings-at-home-growing-up', 'How feelings were handled where you grew up', 'Five prompts about the emotional weather of the house you grew up in. Most of what we do with feelings now was learned by watching, long before anyone explained it.', 'Emotions', 'prompts', 8, 196),
  ('what-you-reach-for', 'What you reach for when a feeling is too big', 'Choose the things you actually reach for when a feeling gets bigger than you want to sit with. Not the things you should do; the ones you do. Nothing here is a confession.', 'Emotions', 'pick', 4, 197),
  ('savoring-on-purpose', 'Savoring on purpose', 'Three minutes of deliberately holding on to a good feeling. Most people are well practiced at replaying bad moments; this practices the other direction.', 'Emotions', 'guide', 5, 198),
  ('how-feelings-do-the-driving', 'How much your feelings do the driving', 'Rate how often a feeling has been the one making your decisions lately, from canceling plans to sending the message. Feelings are useful passengers; the question is who has the wheel.', 'Emotions', 'reflect', 5, 199),
  ('anger-early-cues', 'Your early cues for anger', 'Tick the signs that show up in you before anger fully arrives. The earlier the cue you can catch, the more choice you have.', 'Anger', 'check', 3, 200),
  ('anger-triggers-grid', 'What sets you off, and how hard', 'Place your triggers on a grid of how often they happen against how intense your reaction is. The top-right corner is where most of the damage happens.', 'Anger', 'matrix', 6, 201),
  ('cool-down-plan', 'Build your cool-down', 'Assemble a plan for the ninety seconds after you notice anger rising: how you pause, what you do with your body, and what you say.', 'Anger', 'build', 5, 202),
  ('under-the-anger', 'What was under the anger', 'Think of a recent time you were angry and pick the other feelings that were there too. Anger is often the loudest of several.', 'Anger', 'pick', 4, 203),
  ('how-your-anger-comes-out', 'How your anger comes out', 'Rate how often anger takes each of several shapes in you: the explosion, the slow simmer, the cold silence, the joke with an edge. Most people have a main one and a backup.', 'Anger', 'reflect', 5, 204),
  ('anger-dials', 'The shape of your anger, on dials', 'Set a dial for how your anger tends to behave: how fast it rises, how loud it gets, how long it lingers, how much you remember afterwards. There is no right shape, only yours.', 'Anger', 'sliders', 4, 205),
  ('said-half-said-never-said', 'Said, half-said, never said', 'Sort the things you are quietly resentful about by whether you have actually raised them. Unspoken resentments have a way of coming out sideways.', 'Anger', 'sort', 6, 206),
  ('after-the-blowup', 'After the blowup', 'Walk one recent angry moment through what happened, what you did, what you wish you had done, and what a repair might look like. Honest, private, and not a trial.', 'Anger', 'prompts', 9, 207),
  ('fuse-shorteners', 'What has been shortening your fuse', 'Tick the conditions that have been true lately: too little sleep, skipped meals, no time alone, a body in pain. Anger is often more about the state you are in than the thing in front of you.', 'Anger', 'check', 3, 208),
  ('brake-pedal-breath', 'The brake pedal breath', 'Four seconds in, four held, eight out, six times. The hold is the point: it puts a deliberate gap between the heat and whatever you do next.', 'Anger', 'breathe', 3, 209),
  ('let-the-heat-move', 'Let the heat move', 'A short physical exercise for anger that is stuck in the body: push, shake, unclench, exhale, and then say one true sentence. Best done somewhere you can move freely.', 'Anger', 'guide', 6, 210),
  ('seven-days-of-your-fuse', 'Seven days of your fuse', 'Each day, note how short your fuse was, how strong the strongest flare was, and how quickly you came back down. After a few days the shape of the week shows itself.', 'Anger', 'track', 2, 211),
  ('which-anger-is-it', 'Which anger is it?', 'Anger is not one feeling. Narrow the one you are carrying down from a rough word to a precise one, find where it sits, and hear what it is asking for.', 'Anger', 'wheel', 3, 212),
  ('rules-your-anger-runs-on', 'The rules your anger runs on', 'Turn over cards that show an unspoken rule anger tends to follow on one side and another way of seeing it on the other. Keep the ones that loosen something.', 'Anger', 'flip', 5, 213),
  ('what-your-anger-is-guarding', 'What your anger is guarding', 'Rank what your anger is most often protecting: your dignity, your time, someone you love, being right, being safe. Anger nearly always stands in front of something.', 'Anger', 'rank', 4, 214),
  ('who-gets-your-anger', 'Who gets your anger', 'Divide 100 points across the people and things that actually receive your anger. Where it lands and where it started are often two different places.', 'Anger', 'allocate', 4, 215),
  ('when-your-fuse-is-shortest', 'When your fuse is shortest', 'Mark the days and times of the week when you are most likely to snap. Almost everyone has a danger slot, and it is usually about what surrounds it, not who is in it.', 'Anger', 'heat', 3, 216),
  ('the-anger-you-grew-up-around', 'The anger you grew up around', 'Write about how anger was done in the house you grew up in: who was allowed it, what it looked like, what you copied, and what you swore you would never do.', 'Anger', 'prompts', 10, 217),
  ('where-swallowed-anger-goes', 'Where swallowed anger goes', 'Choose what you tend to do with anger you cannot or will not express: clean, scroll, eat, go quiet, vent to a third person. Anger that is not said still goes somewhere.', 'Anger', 'pick', 4, 218),
  ('say-it-before-it-boils', 'Say it before it boils', 'Assemble a short script for naming irritation early, while it is still small enough to say calmly: how you open, what you name, what you ask for, and what you do if it does not land.', 'Anger', 'build', 5, 219),
  ('after-a-change-dials', 'After a big change: where you have landed', 'Set a dial for how settled you feel in each area of life since a major change: a move, a loss, a breakup, a new role, hard news about a family member''s health.', 'Grief & change', 'sliders', 4, 220),
  ('grief-waves-log', 'Grief in waves: a week', 'Each day, note how heavy the grief was, how close the person or thing felt, and how much you let yourself feel it. It does not move in a straight line.', 'Grief & change', 'track', 2, 221),
  ('what-you-carry', 'What you carry from them', 'Write about someone or something you have lost: what you miss, what you keep, and what you would say now. A quiet, private exercise.', 'Grief & change', 'prompts', 10, 222),
  ('ways-of-remembering', 'Ways of remembering', 'Build a small set of rituals for staying connected to someone or something you have lost: daily, on hard dates, and when a wave hits.', 'Grief & change', 'build', 5, 223),
  ('life-transitions-reflection', 'How you handle transitions', 'Rate how often a set of experiences has been true during a recent period of change: disorientation, second-guessing, unexpected relief, grief for the old version.', 'Grief & change', 'reflect', 5, 224),
  ('what-sets-off-a-wave', 'What sets off a wave, and whether you see it coming', 'Sort the things that bring the loss back by whether you can plan for them, whether they ambush you, or whether you go looking for them. All three are normal.', 'Grief & change', 'sort', 5, 225),
  ('the-shoulds-of-grief', 'The shoulds of grief', 'Turn over cards that show something grief tells you that you should be doing or feeling by now, and another way to see it. Keep the ones that ease something.', 'Grief & change', 'flip', 5, 226),
  ('leaving-a-place', 'Leaving a place', 'For a move, a leaving, or a home that is no longer yours: write about what the place knew about you, what you will miss, and what you are taking with you.', 'Grief & change', 'prompts', 9, 227),
  ('what-ended-when-it-ended', 'What ended when it ended', 'After a breakup, choose what you actually lost: the person, yes, but also the routine, the future you pictured, their family, the nickname. Then rank them. The heaviest is often not the obvious one.', 'Grief & change', 'pick', 5, 228),
  ('what-the-job-was-giving-you', 'What the job was giving you', 'After losing or leaving a job, divide 100 points across what it was actually providing: money, yes, but also structure, identity, people, a reason to get dressed. The biggest bar is what needs replacing first.', 'Grief & change', 'allocate', 4, 229),
  ('when-a-good-change-still-hurts', 'When a good change still hurts', 'For changes you chose and wanted, a baby, a marriage, a move for love, retirement, recovery, coming out: rate how often the grief inside them has been true. Wanting it and missing what it replaced are not in conflict.', 'Grief & change', 'reflect', 5, 230),
  ('when-grief-finds-you', 'When grief finds you in the week', 'Mark the days and times when the loss comes closest. Grief has a timetable: the quiet before sleep, Sunday afternoons, the hour you used to call. Knowing it helps you meet it.', 'Grief & change', 'heat', 3, 231),
  ('five-minutes-with-a-wave', 'Five minutes with a wave', 'A short guided exercise for when a wave of grief hits: stop, let it be there, put a hand where it sits, name what it is missing, and then one small next thing.', 'Grief & change', 'guide', 6, 232),
  ('who-you-can-talk-to-about-it', 'Who you can talk to about it', 'Place the people in your life on a grid of how close they were to what you lost against how easy it is to talk to them about it. The two rarely line up, and that is useful to see.', 'Grief & change', 'matrix', 5, 233),
  ('what-you-need-from-people-now', 'What you need from people right now', 'Rank what you most need from the people around you during this loss or change: to be asked, to be left alone, practical help, distraction, permission to laugh. People want to help and often guess wrong.', 'Grief & change', 'rank', 4, 234),
  ('endings-that-never-got-marked', 'Endings that never got marked', 'Tick the small and medium endings you have been through that nobody held a ceremony for: a friendship that faded, a body that changed, a plan that quietly did not happen. They count.', 'Grief & change', 'check', 4, 235),
  ('breath-for-a-heavy-chest', 'A breath for a heavy chest', 'Four seconds in, six seconds out, seven times. Grief often sits in the chest; this is not to move it, only to make a little room around it.', 'Grief & change', 'breathe', 3, 236),
  ('the-first-weeks-after-a-breakup', 'The first weeks after a breakup', 'Build a plan for the raw first stretch after a relationship ends: their things, the phone, who you tell, and what to do with the hours you used to spend together.', 'Grief & change', 'build', 6, 237),
  ('what-comes-with-you', 'What comes with you', 'For a move, a new job, retirement, or any change of life: sort your habits, people, roles, and routines into what comes with you, what stays behind, and what you are not sure about yet.', 'Grief & change', 'sort', 6, 238),
  ('relief-and-grief-at-the-same-time', 'Relief and grief at the same time', 'For an ending that brought relief as well as loss, after a long illness, a hard relationship, a job that was wearing you down: write about both, without choosing between them.', 'Grief & change', 'prompts', 9, 239),
  ('loneliness-patterns', 'The shape of your loneliness', 'Rate how often a set of loneliness experiences has been true lately: feeling unseen in a crowd, having people but not closeness, missing a particular kind of company.', 'Loneliness', 'reflect', 5, 240),
  ('connection-menu', 'Build your connection menu', 'Assemble a menu of ways to make contact, sized from tiny to brave, so that on a lonely day there is something small enough to actually do.', 'Loneliness', 'build', 5, 241),
  ('social-energy-dials', 'Your social energy, honestly', 'Set dials for how different kinds of social contact affect you. Not a personality label; a map of what fills and what costs.', 'Loneliness', 'sliders', 4, 242),
  ('reaching-out-ladder', 'The reaching-out ladder', 'Rank ways of making contact from easiest to hardest for you. Your ladder is yours; the bottom rungs are where to start on a low day.', 'Loneliness', 'rank', 4, 243),
  ('company-you-miss', 'The company you are missing', 'Choose the kinds of company you are short of right now, then put them in order. Loneliness is usually about one specific gap, not about people in general.', 'Loneliness', 'pick', 5, 244),
  ('lonely-hours-map', 'When loneliness lands in your week', 'Mark the times in a typical week when loneliness is most likely to find you. It is rarely spread evenly; most people have two or three predictable hours.', 'Loneliness', 'heat', 3, 245),
  ('drifted-not-gone', 'Drifted, not gone', 'Place people you have drifted from on a grid of how much you miss them against how easy it would be to reach out. One corner is where a message would pay off most.', 'Loneliness', 'matrix', 6, 246),
  ('what-loneliness-says', 'What loneliness tells you', 'Turn over cards that show something loneliness says in its calm, reasonable voice, and on the back a second look at whether it holds up.', 'Loneliness', 'flip', 5, 247),
  ('week-of-contact-log', 'A week of contact and loneliness', 'Each day, log how much real contact you had, how lonely you felt, and whether you reached out to anyone. After a few days the relationship between the three gets clearer.', 'Loneliness', 'track', 2, 248),
  ('lonely-evening-moves', 'What you do with a lonely evening', 'Sort the things you reach for on a lonely evening by how they leave you afterwards. Some pass the time, some make it worse, and a few actually help.', 'Loneliness', 'sort', 5, 249),
  ('message-you-havent-sent', 'The message you have not sent', 'Write your way toward a message to someone you have drifted from: who, what has stopped you, what you would actually say, and the smallest version you could send.', 'Loneliness', 'prompts', 8, 250),
  ('week-in-company', 'Your week in company', 'Divide 100 points across the kinds of time in a typical week: alone by choice, alone by default, around people, and truly with people. The gaps between the bars are the story.', 'Loneliness', 'allocate', 4, 251),
  ('who-would-you-tell', 'Who would you tell?', 'Tick the gaps in being known that fit your life right now. Loneliness is often less about company and more about having no one who holds the details.', 'Loneliness', 'check', 3, 252),
  ('alone-or-lonely-dials', 'Alone or lonely?', 'Set dials that separate solitude from loneliness. Time alone can be restful or heavy, chosen or imposed, and the difference is easy to miss from the inside.', 'Loneliness', 'sliders', 4, 253),
  ('one-call-right-now', 'One call, right now', 'A guided reach-out you do live: pick a person, decide what you will say, settle for a minute, make the call or send the voice note, then notice what it was actually like.', 'Loneliness', 'guide', 8, 254),
  ('when-you-belonged', 'A time you belonged', 'Remember a time you had a place among people, then take it apart to see what made it work and which of those parts you could rebuild now.', 'Loneliness', 'prompts', 9, 255),
  ('become-a-regular', 'Become a regular somewhere', 'Assemble a plan for one standing place in your week where people come to expect you. Regularity is how strangers turn into familiar faces and familiar faces into friends.', 'Loneliness', 'build', 5, 256),
  ('hand-on-heart', 'Hand on heart', 'A slow breath with one hand resting on your chest, for a lonely night. The warmth and weight of your own hand does more than it sounds like it should.', 'Loneliness', 'breathe', 3, 257),
  ('ways-you-pull-back', 'The ways you pull back', 'Tick the small withdrawals you recognize from the last couple of weeks. Loneliness and pulling back feed each other, and the pulling back is the part you can actually see.', 'Loneliness', 'check', 3, 258),
  ('where-to-find-your-people', 'Where to look for your people', 'Order places you could meet people by how well they fit you, not by how good they sound. The best place to look is the one you would actually go back to.', 'Loneliness', 'rank', 4, 259),
  ('attention-week-map', 'When your attention is sharpest', 'Mark the times in your week when you can actually concentrate. Most people schedule their hardest work at their worst times without knowing it.', 'Focus', 'heat', 3, 260),
  ('what-pulls-you-away', 'What pulls you away', 'Sort your distractions into ones that come from outside, ones that come from inside, and ones that are both. Each kind wants a different fix.', 'Focus', 'sort', 4, 261),
  ('focus-conditions', 'The conditions you focus best under', 'Choose the conditions that genuinely help you concentrate. Not what productivity advice says; what has actually worked for you.', 'Focus', 'pick', 4, 262),
  ('getting-started-friction', 'The friction of getting started', 'Rate how often a set of starting struggles has been true lately: circling a task, needing the perfect moment, finishing easy things to avoid the hard one.', 'Focus', 'reflect', 5, 263),
  ('one-thing-for-ten-minutes', 'One thing for ten minutes', 'A guided single-task session: choose one thing, set the conditions, work for ten minutes, then notice what happened in your attention.', 'Focus', 'guide', 14, 264),
  ('where-an-hour-goes', 'Where an hour actually goes', 'Divide 100 points across what a typical working hour really contains: the task, the phone, messages, drifting, getting up, and finding your place again. Most people overestimate the first bar.', 'Focus', 'allocate', 4, 265),
  ('clear-or-wanted', 'Clear or wanted', 'Place tasks on a grid of how clear the next step is against how much you want to do them. Each corner stalls for a different reason and needs a different push.', 'Focus', 'matrix', 6, 266),
  ('seven-days-of-attention', 'Seven days of attention', 'Each day, rate how easily you got started, how long your longest unbroken stretch felt, and how much of the day went where you meant it to. A week is more honest than any single day.', 'Focus', 'track', 2, 267),
  ('close-one-open-the-next', 'Close one, open the next', 'Four slow breaths to close one task before opening the next. Attention drags the last thing into the next thing unless you give it a moment to let go.', 'Focus', 'breathe', 2, 268),
  ('focus-stories', 'Things you tell yourself about focus', 'Turn over cards that show a familiar story about how you work on one side, and on the other a way to check whether it is true today, for this task.', 'Focus', 'flip', 5, 269),
  ('the-last-ten-percent', 'The last ten percent', 'Rate how often a set of finishing struggles has been true lately: losing interest near the end, polishing instead of closing, leaving things almost done. Starting gets all the attention; finishing has its own friction.', 'Focus', 'reflect', 5, 270),
  ('attention-has-left', 'Signs your attention has already left', 'Tick the tells you recognize from the moments when you are still at the task but no longer really on it. Catching these ten seconds earlier is most of the skill.', 'Focus', 'check', 3, 271),
  ('coming-back-after-interruption', 'Coming back after an interruption', 'A short guided routine for the minutes after someone or something breaks your concentration: mark where you were, close the intruder, settle, and re-enter without the usual long drift.', 'Focus', 'guide', 6, 272),
  ('interruption-plan', 'Build your interruption plan', 'Assemble defenses for the three sources of interruption: devices, people, and your own wandering mind. Each needs a different move, and they only work if you decide them in advance.', 'Focus', 'build', 5, 273),
  ('order-of-your-day', 'The order of your day', 'Rank the kinds of work you do by when they belong in your day, from first thing to last. Most people put the easiest, most interrupting work first and wonder where the good hours went.', 'Focus', 'rank', 4, 274),
  ('what-holds-your-attention', 'What holds your attention, and what does not', 'Set a dial for how easily you sink into different kinds of activity. Attention is not one thing; most people have a couple of activities where it comes free and a couple where it never does.', 'Focus', 'sliders', 4, 275),
  ('reverse-engineer-a-good-session', 'Reverse-engineer a good session', 'Take apart a recent time when your attention actually held: what the task was, what got you in, what kept you there, what nearly broke it, and what you could copy on purpose.', 'Focus', 'prompts', 8, 276),
  ('task-under-the-distraction', 'The task under the distraction', 'For the moment you catch yourself scrolling or wandering. Five quick prompts to name what you were supposed to be doing, what about it made you leave, and what would make the next five minutes possible.', 'Focus', 'prompts', 4, 277),
  ('why-tasks-stall', 'Why tasks stall for you', 'Sort everyday tasks by the reason they tend to stall for you: unclear, dull, or uncomfortable. Each reason has a different fix, and most people reach for the wrong one by default.', 'Focus', 'sort', 5, 278),
  ('breaks-that-give-back', 'Breaks that actually give something back', 'Choose the breaks that genuinely restore your attention rather than quietly draining it. The difference is obvious in hindsight and nearly invisible at the time.', 'Focus', 'pick', 4, 279),
  ('morning-routine-builder', 'Design a morning you would actually do', 'Build a realistic morning from pieces you would keep on a tired Tuesday, not an aspirational one you would abandon by the weekend.', 'Habits', 'build', 5, 280),
  ('habit-ease-vs-impact', 'Habits: ease against impact', 'Place the habits you are thinking about on a grid of how easy they would be to start against how much difference they would make.', 'Habits', 'matrix', 5, 281),
  ('tiny-habit-log', 'A week of one tiny habit', 'Pick one small habit and log each day whether you did it and how you felt afterwards. A week is enough to learn whether it is the right habit.', 'Habits', 'track', 2, 282),
  ('daily-rhythm-check', 'The basics of a daily rhythm', 'Tick the everyday rhythms that are currently in place: light, meals, movement, contact, sleep timing. Mood often follows rhythm more than we expect.', 'Habits', 'check', 3, 283),
  ('which-habit-first', 'Which habit first', 'Rank a list of common habit changes by which would most improve your life right now. Ranking forces a choice that a to-do list lets you avoid.', 'Habits', 'rank', 4, 284),
  ('one-habit-taken-apart', 'One habit, taken apart', 'Walk through a single habit you already have, good or otherwise: what comes right before it, what it gives you in the moment, and what it costs later.', 'Habits', 'prompts', 7, 285),
  ('how-habits-slip', 'How your habits tend to slip', 'Rate how often a set of common ways habits fade has been true for you. Most people slip the same way every time, and knowing the way is half of catching it.', 'Habits', 'reflect', 5, 286),
  ('where-the-friction-is', 'Where the friction is', 'Set a dial for each stage of one habit, from remembering it to restarting after a miss. Most habits fail at one stage, not all of them, and the fix depends on which.', 'Habits', 'sliders', 4, 287),
  ('keep-tweak-let-go', 'Keep, tweak, or let go', 'Sort the habits you already have into ones to keep as they are, ones that need a small adjustment, and ones you are ready to let go of.', 'Habits', 'sort', 5, 288),
  ('anchors-already-in-your-day', 'Anchors already in your day', 'Choose the things that already happen every day without effort. A new habit attached to one of them sticks far faster than one that floats.', 'Habits', 'pick', 3, 289),
  ('when-the-habit-happens', 'When the habit actually happens', 'Mark the times across a typical week when one habit you are building actually gets done. The empty slots are not failures; they are the wrong slots.', 'Habits', 'heat', 3, 290),
  ('sentences-that-end-a-habit', 'The sentences that end a habit', 'Turn over cards that show a sentence people say right before a habit stops, with a question on the back that keeps it going a little longer.', 'Habits', 'flip', 5, 291),
  ('coming-back-after-a-miss', 'Coming back after a miss', 'A short guided restart for a habit that has slipped: name the gap, notice the story attached to it, shrink the habit, and do the two-minute version now.', 'Habits', 'guide', 6, 292),
  ('what-runs-on-autopilot', 'What runs on autopilot', 'Divide 100 points across what fills the unplanned gaps in your day: the five minutes waiting, the hour after dinner. Gaps get filled by whatever is closest.', 'Habits', 'allocate', 4, 293),
  ('bad-day-versions', 'The bad-day version of your habits', 'Build a set of habits shrunk to the size you could manage on your worst realistic day. A tiny version kept alive is easy to grow again; a habit dropped is not.', 'Habits', 'build', 5, 294),
  ('signs-a-habit-has-taken-hold', 'Signs a habit has taken hold', 'Tick the signs that a habit you have been building has become automatic. Knowing where it is on the way to sticking tells you whether to hold steady or grow it.', 'Habits', 'check', 3, 295),
  ('chosen-or-drifted-into', 'Chosen or drifted into', 'Sort the routines that make up your days by whether you chose them or drifted into them. Most habits arrive by drift, and drifted habits serve whoever built the surroundings.', 'Habits', 'sort', 5, 296),
  ('what-you-believe-about-changing', 'What you believe about changing', 'Rate how often a set of beliefs about habits and change runs your thinking. Beliefs about size, speed, and perfection end more habits than any missed day does.', 'Habits', 'reflect', 5, 297),
  ('now-versus-later', 'Now versus later', 'Place the habits you already have on a grid of how good they feel right now against how good they are for you later. The corners tell you what each one needs.', 'Habits', 'matrix', 5, 298),
  ('the-person-who-does-that', 'The person who does that', 'Instead of planning a habit, describe the kind of person for whom it is simply normal, then find where you are already a little like them.', 'Habits', 'prompts', 7, 299),
  ('values-card-sort', 'The values card sort', 'Choose the five values that matter most to you from a long list, then rank them. A clear list makes daily decisions noticeably simpler.', 'Values & meaning', 'pick', 6, 300),
  ('life-areas-wheel', 'The life areas wheel', 'Rate your satisfaction in eight areas of life. The shape that appears shows where things are full and where they have gone quiet.', 'Values & meaning', 'sliders', 4, 301),
  ('moments-of-meaning', 'Moments of meaning', 'Write about times when life felt meaningful, then look for what they have in common. Meaning usually has a pattern, and the pattern is a map.', 'Values & meaning', 'prompts', 8, 302),
  ('time-vs-what-matters', 'Where your time goes versus what matters', 'Divide 100 points across how you actually spent your waking hours last week. Then hold it next to your values and see what the gap says.', 'Values & meaning', 'allocate', 4, 303),
  ('letter-from-future-you', 'A letter from five years on', 'Write to yourself from five years in the future, from a version of you who came through what you are in now. It is a way of hearing what you already know.', 'Values & meaning', 'prompts', 10, 304),
  ('values-you-acted-on', 'Values you acted on this week', 'Tick the things you actually did in the last seven days that expressed a value, even once and even small. Lived values are sometimes a different list from written ones.', 'Values & meaning', 'check', 3, 305),
  ('wanted-against-expected', 'What you want against what is expected', 'Place the big shapes of your life on a grid of how much you actually want each one against how much it is expected of you. One corner is where quiet resentment grows.', 'Values & meaning', 'matrix', 6, 306),
  ('whose-rule-is-it', 'Whose rule is it', 'Sort the "shoulds" that follow you around by whether they match what you value or belong to someone else. A borrowed rule costs the same energy as one you chose.', 'Values & meaning', 'sort', 5, 307),
  ('when-the-week-feels-like-yours', 'When the week feels like yours', 'Mark the times across a typical week when what you are doing feels like it is genuinely yours. The slots are usually few, and they are worth protecting first.', 'Values & meaning', 'heat', 3, 308),
  ('what-pride-and-regret-point-to', 'What pride and regret point to', 'Write about one thing you are quietly proud of and one you regret, then find the value underneath each. Both point at what matters, from opposite ends.', 'Values & meaning', 'prompts', 8, 309),
  ('drifting-from-what-matters', 'How far you have drifted from what matters', 'Rate how often a set of signs of living off-course from your own values has been true lately. Drift is gradual, and nobody notices it from inside until it is pointed out.', 'Values & meaning', 'reflect', 5, 310),
  ('what-enough-looks-like', 'What "enough" looks like for you', 'Set a dial for how close you feel to having enough in areas where "more" is the default. The dials sitting highest are where more will never quite land.', 'Values & meaning', 'sliders', 4, 311),
  ('when-nothing-seems-to-matter', 'When nothing seems to matter', 'Turn over cards that show a thought that flattens meaning, with a question and another angle on the back. Keep the ones that loosen something.', 'Values & meaning', 'flip', 5, 312),
  ('the-advice-you-keep-giving', 'The advice you keep giving', 'The advice you repeat to friends is your values in their most honest form, because you give it without having to live it. Write it down, then turn it around.', 'Values & meaning', 'prompts', 6, 313),
  ('seven-days-on-purpose', 'Seven days of on purpose', 'Each evening, rate how much of the day was chosen rather than drifted, how much of it mattered, and how much of it felt like you. Not how good it was; how much of it was yours.', 'Values & meaning', 'track', 2, 314),
  ('one-value-on-the-calendar', 'Put one value on the calendar', 'Assemble a week with one small, real action for each of your values. A value with no slot in the calendar loses to whatever has one.', 'Values & meaning', 'build', 5, 315),
  ('what-you-admire', 'What you admire in the people you admire', 'Think of a few people you admire and choose the qualities you admire most in them, then rank them. What you admire in others is what you value and may not yet give yourself permission to pursue.', 'Values & meaning', 'pick', 5, 316),
  ('what-you-would-give-up-last', 'What you would give up last', 'Rank a list of things by how hard you would fight to keep each one. What you would give up last is what you value most, whatever you would say if asked directly.', 'Values & meaning', 'rank', 4, 317),
  ('a-decision-held-up', 'A decision, held up to your values', 'A short guided exercise for one live decision: walk each path six months forward, notice what your body does, and name what each path protects.', 'Values & meaning', 'guide', 7, 318),
  ('where-meaning-comes-from', 'Where meaning comes from', 'Divide 100 points across the sources meaning actually came from in the last month, not where it is supposed to come from. One tall bar is a gift and a risk.', 'Values & meaning', 'allocate', 4, 319),
  ('workday-stress-map', 'Where stress lands in your workday', 'Mark the times in your working week when pressure peaks. Once you can see the pattern, you can decide what goes next to it.', 'Work & school', 'heat', 3, 320),
  ('what-you-need-from-work', 'What you need from work', 'Choose and rank the things you most need from work or study to feel okay. When something at work feels wrong, this list usually shows what is missing.', 'Work & school', 'pick', 5, 321),
  ('demands-vs-control', 'Demands against control', 'Place the parts of your work or study on a grid of how demanding they are against how much say you have over them. High demand with low control is where strain tends to live.', 'Work & school', 'matrix', 6, 322),
  ('end-of-day-shutdown', 'Build an end-of-day shutdown', 'Design a short routine that tells your brain the working day is over, so it stops running the day back at dinner and at 2 a.m.', 'Work & school', 'build', 5, 323),
  ('how-feedback-lands', 'How feedback lands on you', 'Rate how often a set of common reactions to feedback at work or school has been true for you lately: the praise you wave away, the criticism you replay, the review you dread.', 'Work & school', 'reflect', 5, 324),
  ('one-meeting-six-dials', 'One meeting, six dials', 'Pick one recurring meeting or class and set six dials for how it actually goes for you. It is usually not the meeting that is the problem; it is one or two settings on it.', 'Work & school', 'sliders', 4, 325),
  ('how-you-meet-a-deadline', 'How you meet a deadline', 'Sort your deadline habits by whether they help you, cost you, or both at once. Most people run on a mix and have never looked at which is which.', 'Work & school', 'sort', 5, 326),
  ('the-person-who-grades-you', 'The person who grades you', 'Write your way through your relationship with a manager, supervisor, or teacher: what they seem to want, what you assume about them, and what actually happens when it goes well.', 'Work & school', 'prompts', 8, 327),
  ('sunday-evening-signals', 'Sunday evening signals', 'Tick the ways the week ahead announces itself on the evening before it starts. The Sunday feeling has parts, and the parts point at different things.', 'Work & school', 'check', 3, 328),
  ('signs-remote-work-has-drifted', 'Signs remote work has drifted', 'For anyone who works or studies from home. Tick the small drifts that happen when there is no building to leave, no commute to end the day, and no one to see you not taking a break.', 'Work & school', 'check', 3, 329),
  ('three-breaths-before-the-call', 'Three breaths before the call', 'A very short paced breath for the minute before you join a meeting, walk into a classroom, or hit send on a message you have rewritten five times.', 'Work & school', 'breathe', 1, 330),
  ('speaking-up-in-the-room', 'Speaking up in the room', 'A guided run-through for the moment before you say something in a meeting or a class: notice the sentence, shrink it, wait for the gap, and say it before the gap closes.', 'Work & school', 'guide', 6, 331),
  ('seven-workdays-log', 'Seven workdays, logged', 'Each day, rate how much of the day felt like real work, how you felt at the end of it, and how connected you were to the people around you. After a week the three lines tell a story about your job or your course.', 'Work & school', 'track', 2, 332),
  ('what-a-coworker-might-mean', 'What a coworker might mean', 'Turn over cards that show something a coworker or classmate did on one side and the other readings of it on the back. The first story we tell ourselves is rarely the only one.', 'Work & school', 'flip', 5, 333),
  ('where-the-working-week-goes', 'Where the working week goes', 'Divide 100 points across the things that fill a typical working or study week, honestly. Most people find the "actual work" bar smaller than they expected and the "waiting and worrying" bar larger.', 'Work & school', 'allocate', 4, 334),
  ('the-asking-ladder-at-work', 'The asking ladder at work', 'Rank the things people ask for at work or school from easiest to hardest for you. Everyone has a ladder; the surprising part is usually which rung is at the top.', 'Work & school', 'rank', 4, 335),
  ('prepare-a-hard-conversation-at-work', 'Prepare a hard conversation at work', 'Assemble a plan for a conversation you have been putting off with a manager, a coworker, a teacher, or a teammate: what you want them to know, what you are asking for, and how you will open.', 'Work & school', 'build', 7, 336),
  ('the-role-you-play-on-a-team', 'The role you play on a team', 'Choose the parts you tend to play in a team, a class, or a group project, then put them in order. Some are chosen; some were handed to you a long time ago and never given back.', 'Work & school', 'pick', 5, 337),
  ('the-student-load', 'The student load', 'For anyone studying, full-time or alongside a job. Set a dial for how much weight each part of student life is carrying right now. The heaviest dial is rarely the coursework.', 'Work & school', 'sliders', 4, 338),
  ('after-a-mistake-at-work', 'After a mistake at work', 'Write through one mistake you made at work or school: what actually happened, what you have told yourself since, and what someone fair would say about it.', 'Work & school', 'prompts', 7, 339),
  ('five-senses-grounding', 'Five senses grounding', 'Five things you can see, four you can touch, three you can hear, two you can smell, one you can taste. A way back into the room when your mind has left it.', 'Calm & grounding', 'guide', 4, 340),
  ('tense-and-release', 'Tense and release', 'Work through the body tightening each muscle group for a few seconds and then letting go. Many people do not notice how much they are holding until they let it drop.', 'Calm & grounding', 'guide', 8, 341),
  ('coherent-breathing', 'Coherent breathing', 'Five seconds in, five seconds out, no holds. A steady, even rhythm many people find easiest to keep up for a few minutes at a time.', 'Calm & grounding', 'breathe', 4, 342),
  ('the-long-exhale', 'The long exhale', 'Four seconds in, eight seconds out, no holds. Making the out-breath twice as long as the in-breath is one of the simplest ways many people find to settle a body that is running fast.', 'Calm & grounding', 'breathe', 3, 343),
  ('the-double-breath', 'The double breath', 'Two breaths in through the nose, the second one a small top-up, then one long breath out through the mouth. The shape of a sigh, done deliberately, a handful of times.', 'Calm & grounding', 'breathe', 2, 344),
  ('the-humming-breath', 'The humming breath', 'Breathe in through the nose, then hum the whole way out. The vibration in the chest and face gives the mind something to rest on, and the hum stretches the out-breath without any counting.', 'Calm & grounding', 'breathe', 3, 345),
  ('cold-water-reset', 'The cold water reset', 'A guided minute with cold water on the face, the wrists, or the back of the neck. A fast, physical way many people use to interrupt a spiral when breathing alone is not reaching it.', 'Calm & grounding', 'guide', 4, 346),
  ('a-slow-walk-felt-from-the-feet', 'A slow walk, felt from the feet', 'Five minutes of walking slower than feels natural, with attention kept in the soles of the feet. Grounding that uses the whole body, for people who cannot sit still to calm down.', 'Calm & grounding', 'guide', 7, 347),
  ('what-gets-between-you-and-calm', 'What gets between you and calm', 'Sort the things that keep you from settling by how much say you have over them. Some of what makes life loud can be turned down; some can only be worked around, and it helps to know which is which.', 'Calm & grounding', 'sort', 5, 348),
  ('how-you-know-you-are-settling', 'How you know you are settling', 'Choose the signs your body gives when calm starts to arrive. Most people know their signs for stress in detail and their signs for settling not at all, which makes the calm easy to miss.', 'Calm & grounding', 'pick', 4, 349),
  ('where-you-are-right-now', 'Where you are right now, on six dials', 'A one-minute check-in on the state you are in at this moment: the breath, the muscles, the speed of thought, and how much of the room you can feel. Useful before and after anything meant to settle you.', 'Calm & grounding', 'sliders', 2, 350),
  ('how-you-relate-to-quiet', 'How you relate to quiet', 'Rate how often a set of habits around stillness has been true for you lately. For some people calm is a relief; for others it is a gap that has to be filled fast, and it helps to know which you are.', 'Calm & grounding', 'reflect', 5, 351),
  ('signs-your-body-is-on-alert', 'Signs your body is on alert', 'Tick the small ways a body shows it has not fully stood down: the startle, the scanning, the jaw. These are the habits grounding is meant to loosen, and the first step is knowing yours.', 'Calm & grounding', 'check', 3, 352),
  ('a-memory-of-calm-in-detail', 'A memory of calm, in detail', 'Write your way back into one moment when you felt fully at ease, sense by sense, until you can find the part of it you could bring into the room you are in now.', 'Calm & grounding', 'prompts', 7, 353),
  ('seven-days-of-settling', 'Seven days of settling', 'Each evening, rate how settled you felt overall, how much you moved your body, and how much of the day was spent off a screen. After a week the three lines start to explain each other.', 'Calm & grounding', 'track', 2, 354),
  ('design-a-calm-corner', 'Design a calm corner', 'Plan one small spot at home, or wherever you spend your days, that is set up for settling: where it is, what is in it, what is kept out, and the signal that tells you it is time to use it.', 'Calm & grounding', 'build', 6, 355),
  ('things-people-believe-about-calm', 'Things people believe about calm', 'Turn over cards that show a common belief about being calm on one side and a more forgiving angle on the back. A lot of what makes calm hard to reach is the idea of what it is supposed to look like.', 'Calm & grounding', 'flip', 5, 356),
  ('soothing-or-numbing', 'Soothing or numbing', 'Place the things you reach for when you need to feel better on a grid of how often you reach for them against how you actually feel afterwards. Both corners feel like calm in the moment; only one still does an hour later.', 'Calm & grounding', 'matrix', 6, 357),
  ('your-grounding-order', 'Your grounding order', 'Rank a set of grounding moves from the one you trust most to the one you trust least. Everybody''s order is different, and knowing yours means you do not have to think when it is loud.', 'Calm & grounding', 'rank', 4, 358),
  ('when-you-feel-most-settled', 'When you feel most settled', 'Mark the times in a typical week when you feel most at ease. Most week maps track the trouble; this one maps the calm, so you can see where it already lives and put more next to it.', 'Calm & grounding', 'heat', 3, 359)
